import React from 'react';
import { ExternalLink } from 'lucide-react';
import { FaGithub } from 'react-icons/fa';
export const ProjectCard = ({
  project,
  index = 0
}) => {
  const isEven = index % 2 === 0;

  // Property mapping fallbacks for type flexibility
  const projectWithLinks = project;
  const githubUrl = projectWithLinks.githubUrl || projectWithLinks.githubLink;
  const liveUrl = projectWithLinks.liveUrl || projectWithLinks.liveLink;
  return <div className={`relative flex flex-col ${isEven ? 'md:flex-row' : 'md:flex-row-reverse'} items-center justify-center gap-8 md:gap-0 my-16 font-preahvihear select-none w-full`}>
      {/* Background Radial Glow */}
      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[450px] h-[300px] bg-purple-600/10 rounded-full blur-[100px] -z-10 pointer-events-none" />

      {/* Project Visual Container */}
      <div className="w-full md:w-[55%] h-[260px] md:h-[340px] bg-[#0E0720] rounded-xl border border-purple-900/40 overflow-hidden shadow-2xl relative group">
        {project.image ? <img src={project.image} alt={project.title} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" /> : <div className="w-full h-full bg-[#130B29] p-4 flex flex-col justify-between border border-purple-500/20">
            <div className="w-full h-6 border-b border-purple-500/20 flex items-center gap-2 px-2">
              <div className="w-2.5 h-2.5 rounded-full bg-red-500/60" />
              <div className="w-2.5 h-2.5 rounded-full bg-yellow-500/60" />
              <div className="w-2.5 h-2.5 rounded-full bg-green-500/60" />
            </div>
            <div className="flex-1 flex flex-col items-center justify-center text-center p-6 text-purple-300/40">
              <p className="text-sm uppercase tracking-widest mb-1">Project Frame</p>
              <h4 className="text-xl font-bold text-purple-200/60">{project.title}</h4>
            </div>
          </div>}
      </div>

      {/* Overlapping Content Box */}
      <div className={`w-full md:w-[50%] flex flex-col ${isEven ? 'md:items-start md:text-left md:-ml-16' : 'md:items-end md:text-right md:-mr-16'} z-10 mt-6 md:mt-0`}>
        <span className="text-xs text-purple-400 font-normal tracking-wide mb-1">
          Featured Project
        </span>
        <h3 className="text-2xl md:text-3xl font-semibold text-white mb-4">
          {project.title}
        </h3>

        {/* Floating Translucent Description Card */}
        <div className="p-6 rounded-xl bg-[#1A0B2E]/80 backdrop-blur-md border border-purple-500/30 shadow-2xl mb-4 text-sm text-gray-300 leading-relaxed max-w-lg">
          {project.description}
        </div>

        {/* Tech Stack */}
        {project.technologies && project.technologies.length > 0 && <div className={`flex flex-wrap gap-3 mb-6 text-xs text-purple-300/80 font-mono ${!isEven && 'md:justify-end'}`}>
            {project.technologies.map((tech, idx) => <span key={idx} className="bg-purple-950/40 px-2.5 py-1 rounded border border-purple-500/20">
                {tech}
              </span>)}
          </div>}

        {/* External Links */}
        <div className="flex items-center gap-5 text-gray-300">
          {githubUrl && <a href={githubUrl} target="_blank" rel="noopener noreferrer" className="hover:text-purple-400 transition-colors duration-200" title="GitHub Repository">
              <FaGithub size={22} />
            </a>}
          {liveUrl && <a href={liveUrl} target="_blank" rel="noopener noreferrer" className="hover:text-purple-400 transition-colors duration-200" title="Live Demo">
              <ExternalLink size={22} />
            </a>}
        </div>
      </div>
    </div>;
};
export default ProjectCard;